  func testCapturedV1ActiveSessionDecodesWithoutV2Fields() throws {
    let session = try JSONDecoder().decode(SharedData.SessionSnapshot.self, from: capturedSession)
    XCTAssertEqual(session.id, "01DCA90F-AFD0-48F7-9088-C57F350318C1")
    XCTAssertEqual(session.blockedProfileId, UUID(uuidString: "5EA9C3BF-2F52-4498-BAE0-6A5E79D4E7EA"))
    XCTAssertEqual(session.tag, "nfc:04AABBCCDD")
    XCTAssertEqual(session.startTime, Date(timeIntervalSinceReferenceDate: 812744462.431182))
    XCTAssertFalse(session.forceStarted)
    XCTAssertFalse(session.oneMoreMinuteUsed)
    XCTAssertNil(session.endTime)
    XCTAssertNil(session.timerEndTime)
    XCTAssertNil(session.breakStartTime)
    XCTAssertNil(session.breakEndTime)
    XCTAssertNil(session.oneMoreMinuteStartTime)
    XCTAssertNil(session.breakEndDeadline)
    XCTAssertNil(session.oneMoreMinuteDeadline)
    XCTAssertNil(session.pinnedProfileConfig)
    XCTAssertNil(session.usesCanonicalIdentity)
    XCTAssertNil(session.origin)
  }

  func testCapturedV1ProfilesDecodeAndRemainOnLegacySchemaPath() throws {
    let profiles = try JSONDecoder().decode([String: SharedData.ProfileSnapshot].self, from: capturedProfiles)
    XCTAssertEqual(profiles.count, 28)
    for (id, profile) in profiles {
      XCTAssertEqual(profile.id.uuidString, id)
      XCTAssertNil(profile.profileSchemaVersion, profile.name)
      XCTAssertNil(profile.startTriggers, profile.name)
    }
    suite.set(capturedProfiles, forKey: "profileSnapshots")
    XCTAssertEqual(SharedData.profileSnapshots.count, 28)
  }

  func testV1ActiveAndCompletedSharedSessionsAllowStopThenNewStart() throws {
    let now = Date(timeIntervalSinceReferenceDate: 812744462.431182 + 600)
    suite.set(capturedSession, forKey: "activeScheduleSession")
    var completed = try XCTUnwrap(JSONSerialization.jsonObject(with: capturedSession) as? [String: Any])
    completed["id"] = "00000000-0000-0000-0000-000000000001"
    completed["endTime"] = now.timeIntervalSinceReferenceDate - 60
    suite.set(try JSONSerialization.data(withJSONObject: [completed]), forKey: "completedScheduleSessions")
    XCTAssertEqual(SharedData.completedSessionsInScheduler.count, 1)
    XCTAssertFalse(try XCTUnwrap(SharedData.completedSessionsInScheduler.first).oneMoreMinuteUsed)
    let active = try XCTUnwrap(SharedData.getActiveSharedSession())
    SharedData.flushActiveSession(expectedSessionId: active.id)
    XCTAssertNil(SharedData.getActiveSharedSession())

    let profile = BlockedProfiles(name: "New manual", createdAt: now, updatedAt: now)
    profile.startTriggers = .init(manual: true)
    profile.stopConditions = .init(manual: true)
    SharedData.setSnapshot(BlockedProfiles.getSnapshot(for: profile), for: profile.id.uuidString)
    let candidate = SharedData.SessionSnapshot(
      id: UUID().uuidString, tag: "manual", blockedProfileId: profile.id,
      startTime: now, forceStarted: false, origin: .init(kind: .manual))
    XCTAssertTrue(SharedData.commitOriginatingSession(candidate, expectedVictimId: nil, now: now))
    XCTAssertEqual(SharedData.getActiveSharedSession()?.id, candidate.id)
    XCTAssertEqual(SharedData.completedSessionsInScheduler.first?.id, completed["id"] as? String)
  }

  func testPresentNullOneMoreMinuteValueIsRejectedWithoutClearingSharedState() throws {
    var json = try XCTUnwrap(JSONSerialization.jsonObject(with: capturedSession) as? [String: Any])
    json["oneMoreMinuteUsed"] = NSNull()
    let malformed = try JSONSerialization.data(withJSONObject: json)
    XCTAssertThrowsError(try JSONDecoder().decode(SharedData.SessionSnapshot.self, from: malformed))
    suite.set(malformed, forKey: "activeScheduleSession")
    SharedData.flushActiveSession(expectedSessionId: "01DCA90F-AFD0-48F7-9088-C57F350318C1")
    XCTAssertEqual(suite.data(forKey: "activeScheduleSession"), malformed)
  }

  func testPresentOneMoreMinuteValueIsRetainedAndWrongTypeIsRejected() throws {
    var json = try XCTUnwrap(JSONSerialization.jsonObject(with: capturedSession) as? [String: Any])
    json["oneMoreMinuteUsed"] = true
    let present = try JSONSerialization.data(withJSONObject: json)
    XCTAssertTrue(try JSONDecoder().decode(SharedData.SessionSnapshot.self, from: present).oneMoreMinuteUsed)
    json["oneMoreMinuteUsed"] = "false"
    let malformed = try JSONSerialization.data(withJSONObject: json)
    XCTAssertThrowsError(try JSONDecoder().decode(SharedData.SessionSnapshot.self, from: malformed))
    suite.set(malformed, forKey: "activeScheduleSession")
    SharedData.flushActiveSession(expectedSessionId: "01DCA90F-AFD0-48F7-9088-C57F350318C1")
    XCTAssertEqual(suite.data(forKey: "activeScheduleSession"), malformed)
  }
